class OpenTripOrderAuditEvaluator(OpenTripHotelVoucherBookingEvaluator):
    """Verify the stored orders and wallet a rescheduling or review task asks for.

    These tasks act on orders that already exist, so the criteria name the
    orders by identifier and state the fields each must then hold -- the status,
    the rescheduled dates, the cabin, or the review that was saved.
    """

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        params = dict(context.get("params") or {})
        if controller is None or not hasattr(controller, "execute_adb"):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="runner-provided controller.execute_adb is required",
                metadata={"read_only": True},
            )

        orders = {
            key: value
            for key, value in params.items()
            if key.endswith("_order") and isinstance(value, Mapping)
        }
        expected_wallet = params.get("wallet") if isinstance(params.get("wallet"), Mapping) else {}
        expected_codes = self._coerce_codes(params.get("redeemed_codes"))
        require_codes = bool(params.get("require_redeemed_codes", False))
        if not orders:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="evaluation requires order expectations",
                metadata={"read_only": True},
            )

        state, error = self._read(controller, params)
        if error is not None:
            return error

        checks: list[dict[str, Any]] = []
        summaries: dict[str, Any] = {}
        for name, expected in sorted(orders.items()):
            order, matches = self._find_order(state, expected)
            checks.append(check(f"{name}_unique", matches == 1, 1, matches))
            if order is not None:
                checks.extend(self._compare_order(name, order, expected))
            summaries[name] = self._summarize_order(order)

        session = state.get("session") if isinstance(state.get("session"), Mapping) else {}
        user = session.get("user") if isinstance(session.get("user"), Mapping) else {}
        checks.append(
            check("session_signed_in", bool(session.get("loggedIn")), True,
                  bool(session.get("loggedIn")))
        )
        wallet = user.get("voucherWallet") if isinstance(user.get("voucherWallet"), Mapping) else {}
        for key, expected_value in expected_wallet.items():
            observed = wallet.get(key)
            checks.append(
                check(f"wallet_{key}", number(observed) == number(expected_value),
                      expected_value, observed)
            )
        redeemed = user.get("redeemedCodes") if isinstance(user.get("redeemedCodes"), list) else []
        observed_codes = [str(code).strip() for code in redeemed]
        for code in expected_codes:
            checks.append(
                check(f"redeemed_code_{code}", code in observed_codes, code, observed_codes)
            )

        return self._verdict(
            checks,
            params,
            require_codes,
            pass_message="OpenTrip orders and wallet match the requested outcome",
            fail_message="OpenTrip orders and wallet do not match the requested outcome",
            extra={"orders": summaries, "wallet": dict(wallet)},
        )

    @staticmethod
    def _find_order(
        state: Mapping[str, Any], expected: Mapping[str, Any]
    ) -> tuple[Mapping[str, Any] | None, int]:
        """Return the single order matching the identifier and type expected."""
        orders = state.get("bookings") if isinstance(state.get("bookings"), list) else []
        found = [
            order
            for order in orders
            if isinstance(order, Mapping)
            and str(order.get("id") or "") == str(expected.get("id") or "")
            and str(order.get("type") or "") == str(expected.get("type") or "")
        ]
        return (found[0] if len(found) == 1 else None), len(found)

    @classmethod
    def _compare_order(
        cls, name: str, order: Mapping[str, Any], expected: Mapping[str, Any]
    ) -> list[dict[str, Any]]:
        """Compare every field the expectation names against one order.

        A field may be stored on the order itself or inside the item the order
        is about, so both are consulted; the comparison is the same either way.
        """
        order_item = order.get("item") if isinstance(order.get("item"), Mapping) else {}
        charges = order.get("charges") if isinstance(order.get("charges"), Mapping) else {}
        # which member of the item holds each expectation field
        item_key_of = {expected_key: item_key for item_key, expected_key in cls.ITEM_FIELDS}
        checks: list[dict[str, Any]] = []
        for key, value in sorted(expected.items()):
            if key in ("id", "type", "charges", "reschedule_history", "review"):
                continue
            observed = None
            if key in item_key_of:
                observed = order_item.get(item_key_of[key])
            if observed is None:
                observed = order.get(key)
            if observed is None:
                observed = order_item.get(key)
            checks.append(
                check(f"{name}_{key}", str(observed or "") == str(value or ""), value, observed)
            )
        for key, value in sorted((expected.get("charges") or {}).items()):
            observed = charges.get(key)
            checks.append(
                check(f"{name}_charges_{key}", number(observed) == number(value), value, observed)
            )
        history = expected.get("reschedule_history")
        if isinstance(history, Mapping):
            recorded = order.get("rescheduleHistory")
            if not isinstance(recorded, Mapping):
                recorded = order_item.get("rescheduleHistory")
            recorded = recorded if isinstance(recorded, Mapping) else {}
            for key, value in sorted(history.items()):
                observed = recorded.get(key)
                checks.append(
                    check(f"{name}_reschedule_{key}",
                          str(observed or "") == str(value or ""), value, observed)
                )
        review = expected.get("review")
        if isinstance(review, Mapping):
            recorded = order.get("review") if isinstance(order.get("review"), Mapping) else {}
            if not recorded:
                recorded = order_item.get("review") if isinstance(order_item.get("review"), Mapping) else {}
            if review.get("require_last_saved") and not recorded:
                checks.append(
                    check(f"{name}_review_saved", False, "a saved review", None)
                )
            if "rating" in review:
                observed = recorded.get("rating")
                checks.append(
                    check(f"{name}_review_rating",
                          number(observed) == number(review["rating"]), review["rating"], observed)
                )
            if "text" in review:
                observed = str(recorded.get("text") or "")
                checks.append(
                    check(f"{name}_review_text", observed == str(review["text"]),
                          review["text"], observed)
                )
        return checks

    @staticmethod
    def _summarize_order(order: Mapping[str, Any] | None) -> dict[str, Any] | None:
        """Reduce an order to the fields a reader needs to see what was found."""
        if not isinstance(order, Mapping):
            return None
        return {
            "id": order.get("id"),
            "type": order.get("type"),
            "status": order.get("status"),
            "cabin": order.get("cabin"),
            "from": (order.get("item") or {}).get("from") if isinstance(order.get("item"), Mapping) else None,
            "to": (order.get("item") or {}).get("to") if isinstance(order.get("item"), Mapping) else None,
            "date": (order.get("item") or {}).get("date") if isinstance(order.get("item"), Mapping) else None,
            "charges": dict(order.get("charges") or {}),
            "review": dict(order.get("review") or {}) if isinstance(order.get("review"), Mapping) else None,
        }


class OpenTripSeedHotelReviewWalletEvaluator(OpenTripOrderAuditEvaluator):
    """Verify a stored stay's saved review together with the voucher wallet.

    A review is only accepted once it has been saved against the order, so the
    rating and text are read back from the order rather than from the form that
    produced them.
    """


class OpenTripSeedOrderRescheduleEvaluator(OpenTripOrderAuditEvaluator):
    """Verify the stored orders after a rescheduling, including their history.

    A rescheduled order keeps both its current values and the record of what was
    changed, so the current dates, cabin and charges are compared alongside the
    recorded rescheduling.
    """


__all__ = [
    "OpenTripFlightVoucherBookingEvaluator",
    "OpenTripHotelVoucherBookingEvaluator",
    "OpenTripOrderAuditEvaluator",
    "OpenTripSeedHotelReviewWalletEvaluator",
    "OpenTripSeedOrderRescheduleEvaluator",
]
